mapper.select:
SELECT l.*, m.member_code, m.name AS member_name, st.name AS store_name, u.nickname AS create_by_name
FROM pos_points_log l
JOIN pos_member m ON m.id = l.member_id
LEFT JOIN store_info st ON st.id = l.store_id
LEFT JOIN sys_user u ON u.id = l.create_by


        (m.phone = #{q.keyword} OR m.member_code = #{q.keyword} OR l.source_no = #{q.keyword})

    AND l.member_id = #{q.memberId}
    AND l.store_id = #{q.storeId}
    AND l.change_type = #{q.changeType}
    AND l.create_time >= #{q.begin}
    AND l.create_time < #{endNext}

ORDER BY l.id DESC
